#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    string word; // word to search
    int count = 0; // counter for word occurrences

    // Prompt user for input word and file name
    cout << "Enter word to search: ";
    getline(cin, word);

    cout << "Enter file name: ";
    string filename;
    getline(cin, filename);

    // Open file for reading
    ifstream file(filename);

    if (!file.is_open()) {
        cout << "Error: Could not open file." << endl;
        return 1;
    }

    // Read file line by line and count occurrences of the word
    string line;
    while (getline(file, line)) {
        size_t pos = 0;
        while ((pos = line.find(word, pos)) != string::npos) {
            count++;
            pos += word.length();
        }
    }

    // Close file
    file.close();

    // Print result
    cout << "The word '" << word << "' appears " << count << " times in the file." << endl;

    return 0;
}
```

This program prompts the user for the word to search and the file name, then reads the file line by line and counts the occurrences of the given word. The result is then printed to the console. Note that this program assumes that the file exists and can be opened, and it does not handle errors related to file permissions or invalid file formats. You may want to add additional error handling to your program based on your specific use case.
